('prod-pol-001','Áo Polo Piqué Essential Đen','ao-polo-pique-essential-den','ACH-POL-001','Áo polo piqué cotton 220gsm, cổ dệt 3 nút, form slim fit. Không logo, không họa tiết.','Polo piqué đen thuần túy cao cấp','cat-001','sub-pol-01','brd-001','UNISEX','Cotton Piqué 220gsm','Giặt máy 30°C, không dùng chất tẩy',450000,NULL,true,true,false,true,234,1200,4.8,47,'250g',ARRAY['polo','den','essential','slim-fit'],'Áo Polo Đen ACHROMATIC','Áo polo piqué đen premium tối giản',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('prod-pol-002','Áo Polo Merino Blend Xám','ao-polo-merino-blend-xam','ACH-POL-002','Merino wool 50% blend, mềm mại không ngứa, tự điều nhiệt. Phù hợp văn phòng lẫn dạo phố.','Polo merino xám sang trọng','cat-001','sub-pol-02','brd-001','UNISEX','Merino Wool 50% Cotton 50%','Giặt tay nước lạnh, phơi phẳng',720000,599000,true,true,true,false,89,680,4.7,23,'260g',ARRAY['polo','merino','xam','wool'],'Áo Polo Merino ACHROMATIC','Áo polo merino blend xám cao cấp',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('prod-pol-003','Áo Polo Piqué Kem Premium','ao-polo-pique-kem-premium','ACH-POL-003','Piqué cotton Ai Cập 100%, màu kem sang trọng, viền cổ tay tương phản.','Polo kem tinh tế cao cấp','cat-001','sub-pol-01','brd-001','UNISEX','Cotton Ai Cập 100% Piqué','Giặt máy 30°C',480000,NULL,false,true,true,false,67,450,4.6,18,'245g',ARRAY['polo','kem','premium','ai-cap'],'Áo Polo Kem ACHROMATIC','Áo polo piqué kem cao cấp',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('prod-pol-004','Áo Polo Classic Navy Viền Trắng','ao-polo-classic-navy-vien-trang','ACH-POL-004','Piqué cotton navy, viền cổ và tay trắng tinh. Phong cách preppy-minimalist cổ điển.','Polo navy viền trắng cổ điển','cat-001','sub-pol-01','brd-001','MALE','Cotton Piqué 220gsm','Giặt máy 30°C, lộn trái',350000,NULL,false,true,false,true,312,1800,4.9,67,'240g',ARRAY['polo','navy','classic','preppy'],'Áo Polo Navy ACHROMATIC','Áo polo navy trắng cổ điển cao cấp',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('prod-pol-005','Áo Polo Olive Performance','ao-polo-olive-performance','ACH-POL-005','Poly-cotton moisture-wicking, màu olive đất, kháng UV. Phù hợp hoạt động ngoài trời.','Polo performance olive kháng UV','cat-001','sub-pol-01','brd-001','UNISEX','Polyester 60% Cotton 40%','Giặt máy 30°C',390000,299000,false,true,false,false,45,320,4.5,12,'230g',ARRAY['polo','olive','performance','uv'],'Áo Polo Olive ACHROMATIC','Áo polo olive performance cao cấp',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('prod-pol-006','Áo Polo Sọc Kẻ Pháp Trắng Đen','ao-polo-soc-ke-phap-trang-den','ACH-POL-006','Sọc ngang Pháp trắng đen, piqué cao cấp, form boxy nhẹ. Cổ điển mà không nhàm.','Polo sọc Breton tối giản','cat-001','sub-pol-01','brd-001','UNISEX','Cotton Piqué 200gsm','Giặt máy 30°C',420000,NULL,false,true,true,false,34,280,4.6,9,'242g',ARRAY['polo','soc','breton','phap'],'Áo Polo Sọc ACHROMATIC','Áo polo sọc ngang Pháp cao cấp',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('prod-pol-007','Áo Polo Quarter-Zip Xám Đậm','ao-polo-quarter-zip-xam-dam','ACH-POL-007','Cổ 1/4 khóa kéo, fleece mịn, phong cách athleisure tinh tế.','Polo quarter-zip athleisure','cat-001','sub-pol-02','brd-001','UNISEX','Cotton Fleece 280gsm','Giặt máy 30°C, không sấy',550000,449000,true,true,true,false,56,420,4.7,15,'270g',ARRAY['polo','quarter-zip','xam-dam','athleisure'],'Áo Polo Quarter-Zip ACHROMATIC','Áo polo quarter-zip xám athleisure',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
